    from collections import defaultdict, deque

    def bfs_color_restrictions(start, end, adj):
        queue = deque([(start, [])])
        visited = set()
        while queue:
            node, path = queue.popleft()
            if node == end:
                return path
            visited.add(node)
            for neighbor in adj[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

    # Build the adjacency list for the tree
    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # Prepare restrictions paths
    restriction_paths = []
    for u, v in restrictions:
        path = bfs_color_restrictions(u, v, adj)
        restriction_paths.append((u, path + [v]))

    # Calculate number of valid paintings
    def is_valid_painting(painting):
        for u, path in restriction_paths:
            if all(painting.get((min(path[i], path[i+1]), max(path[i], path[i+1])), 1) for i in range(len(path) - 1)):
                return False
        return True

    from itertools import product
    valid_count = 0
