            satisfied = False
            break
    return satisfied

def count_valid_paintings(N, edges, M, restrictions):
    graph = defaultdict(set)
    for a, b in edges:
        graph[a].add(b)
        graph[b].add(a)

    def backtrack(node, parent, painted):
        if node == N + 1:
            for u, v in restrictions:
                if u in painted and v in painted:
                    continue
                if not dfs(graph, u, -1, [(x, y) for x, y in restrictions if (x != u or y != v) and (x != v or y != u)]):
                    return 0
            return 1

        count = 0
        painted.add(node)
        count += backtrack(node + 1, node, painted)
        painted.remove(node)
        count += backtrack(node + 1, node, painted)
        return count

    return backtrack(1, -1, set())

